network: bun -e '
const TAG_PUSH = /\bgit\s+tag\b|\bpush\w*\b[^\n]{0,40}?\btags?\b|\btag\s+`?v?\d|\bcreate\w*\b[^\n]{0,40}?\btag\b|\bcut\b[^\n]{0,30}?\b(?:tag|release)\b/i;
const QUOTED_RELEASE = /\bpushes\s+\S+(?:,\s*\S+)*\s+on\s+a\s+\S+\s+tag\b/gi;
const text = `Release storefront combined fix
1. Once T02 and T04 are merged to storefront main branch, push a new
   version tag (e.g. v2.3.1, the next patch after the current 2.3.0)
   matching the v* pattern that triggers storefront release workflow
   (.github/workflows/release.yml), to publish the new ghcr image.
2. Run npm ci, npm test and npm run lint on the tagged commit before
   pushing, to confirm the release artifact is green.
A new ghcr.io/pm-example/storefront image tag is published
containing both T02 and T04 changes.
npm ci, npm test and npm run lint pass on the tagged commit.
`;
const clean = text.replace(QUOTED_RELEASE, "");
console.log("TAG_PUSH test:", TAG_PUSH.test(clean));
const prefix = "v";
console.log("prefix test:", new RegExp("\\b" + prefix + "\\d").test(clean));
'
; web tools: none; explain: none
